        id: Date.now().toString(),
        type: selectedType.toUpperCase(),
        recipients: numGroups,
        date: new Date().toLocaleString(),
        status: 'Sent',
        cost: numGroups,
        sampleMessage: currentPreview,
        providerResponse: res.providerResponse
