export const updateClassFee = async (req: any, res: any): Promise<void> => {
  try {
    const { classId } = req.params;
    const { amount } = req.body;

    let fee = await Fee.findOne({ where: { classId } });
    if (fee) {
      await fee.update({ amount });
    } else {
      fee = await Fee.create({ classId: Number(classId), amount });
    }

    res.json(fee);
  } catch (error) {
    res.status(500).json({ message: 'Error updating fee structure', error });
  }
};

