import { Model, DataTypes, Optional } from 'sequelize';
import sequelize from '../config/database';

interface StaffAttributes {
  id: string;
  staffId: string;
  name: string;
  email: string;
  phone: string;
  role: string;
  subjects: string[];
  photo: string | null;
}

interface StaffCreationAttributes extends Optional<StaffAttributes, 'id' | 'photo'> {}

export class Staff extends Model<StaffAttributes, StaffCreationAttributes> implements StaffAttributes {
  public id!: string;
  public staffId!: string;
  public name!: string;
  public email!: string;
  public phone!: string;
  public role!: string;
  public subjects!: string[];
  public photo!: string | null;

  public readonly createdAt!: Date;
  public readonly updatedAt!: Date;
}

Staff.init({
  id: {
    type: DataTypes.UUID,
    defaultValue: DataTypes.UUIDV4,
    primaryKey: true,
  },
  staffId: {
    type: DataTypes.STRING,
    allowNull: false,
    unique: true,
  },
  name: {
    type: DataTypes.STRING,
    allowNull: false,
  },
  email: {
    type: DataTypes.STRING,
    allowNull: false,
    unique: true,
    validate: { isEmail: true },
  },
  phone: {
    type: DataTypes.STRING,
    allowNull: false,
  },
  role: {
    type: DataTypes.STRING,
    allowNull: false,
  },
  subjects: {
    type: DataTypes.ARRAY(DataTypes.STRING),
    defaultValue: [],
  },
  photo: {
    type: DataTypes.TEXT,
    allowNull: true,
  },
}, {
  sequelize,
  modelName: 'Staff',
  tableName: 'staff_members',
});

export default Staff;

import { Model, DataTypes, Optional } from 'sequelize';
import sequelize from '../config/database';

interface AttendanceAttributes {
  id: number;
  studentId: string;
  date: string; // YYYY-MM-DD
  status: 'Present' | 'Absent' | 'Late';
  remarks: string | null;
}

interface AttendanceCreationAttributes extends Optional<AttendanceAttributes, 'id' | 'remarks'> {}

export class Attendance extends Model<AttendanceAttributes, AttendanceCreationAttributes> implements AttendanceAttributes {
  public id!: number;
  public studentId!: string;
  public date!: string;
  public status!: 'Present' | 'Absent' | 'Late';
  public remarks!: string | null;

  public readonly createdAt!: Date;
  public readonly updatedAt!: Date;
}

Attendance.init({
  id: {
    type: DataTypes.INTEGER,
    autoIncrement: true,
    primaryKey: true,
  },
  studentId: {
    type: DataTypes.UUID,
    allowNull: false,
    references: {
      model: 'students',
      key: 'id',
    },
  },
  date: {
    type: DataTypes.DATEONLY,
    allowNull: false,
  },
  status: {
    type: DataTypes.ENUM('Present', 'Absent', 'Late'),
    allowNull: false,
    defaultValue: 'Present',
  },
  remarks: {
    type: DataTypes.STRING,
    allowNull: true,
  },
}, {
  sequelize,
  modelName: 'Attendance',
  tableName: 'attendance_records',
  indexes: [
    {
      unique: true,
      fields: ['student_id', 'date'],
    },
  ],
});

export default Attendance;

