import { Request, Response } from 'express';
import { Attendance, Student, Class } from '../models';

export const bulkRecordAttendance = async (req: Request, res: Response): Promise<void> => {
  try {
    const { date, records } = req.body; // records: [{ studentId, status, remarks }]

    if (!date || !records || !Array.isArray(records)) {
      res.status(400).json({ message: 'Invalid data format' });
      return;
    }

    const attendancePromises = records.map(record => 
      Attendance.upsert({
        studentId: record.studentId,
        date,
        status: record.status,
        remarks: record.remarks || null
      })
    );

    await Promise.all(attendancePromises);
    res.json({ message: 'Attendance records updated successfully' });
  } catch (error) {
    res.status(500).json({ message: 'Error recording attendance', error });
  }
};

export const getStudentAttendance = async (req: Request, res: Response): Promise<void> => {
  try {
    const { studentId } = req.params;
    const history = await Attendance.findAll({
      where: { studentId },
      order: [['date', 'DESC']]
    });
    res.json(history);
  } catch (error) {
    res.status(500).json({ message: 'Error fetching history', error });
  }
};

export const getClassAttendance = async (req: Request, res: Response): Promise<void> => {
  try {
    const { classId } = req.params;
    const { date } = req.query;

    const history = await Attendance.findAll({
      where: { date: date as string },
      include: [{
        model: Student,
        as: 'student',
        where: { classId }
      }]
    });
    res.json(history);
  } catch (error) {
    res.status(500).json({ message: 'Error fetching class attendance', error });
  }
};

