import axios from 'axios';
import { config } from '../config/env';

export const getAccessToken = async (): Promise<string> => {
  const auth = Buffer.from(`${config.MPESA.CONSUMER_KEY}:${config.MPESA.CONSUMER_SECRET}`).toString('base64');
  const response = await axios.get('https://sandbox.safaricom.co.ke/oauth/v1/generate?grant_type=client_credentials', {
    headers: { Authorization: `Basic ${auth}` }
  });
  return response.data.access_token;
};

export const initiateStkPush = async (phone: string, amount: number, accountReference: string): Promise<any> => {
  const token = await getAccessToken();
  const timestamp = new Date().toISOString().replace(/[^0-9]/g, '').slice(0, 14);
  const password = Buffer.from(`${config.MPESA.SHORTCODE}${config.MPESA.PASSKEY}${timestamp}`).toString('base64');

  const payload = {
    BusinessShortCode: config.MPESA.SHORTCODE,
    Password: password,
    Timestamp: timestamp,
    TransactionType: 'CustomerPayBillOnline',
    Amount: amount,
    PartyA: phone,
    PartyB: config.MPESA.SHORTCODE,
    PhoneNumber: phone,
    CallBackURL: config.MPESA.CALLBACK_URL,
    AccountReference: accountReference,
    TransactionDesc: 'Fee Payment'
  };

  const response = await axios.post('https://sandbox.safaricom.co.ke/mpesa/stkpush/v1/query', payload, {
    headers: { Authorization: `Bearer ${token}` }
  });
  return response.data;
};

import { Request, Response } from 'express';
import { initiateStkPush } from '../services/mpesaService';
import { Payment, Student } from '../models';

export const stkPush = async (req: Request, res: Response): Promise<void> => {
  const { phone, amount, studentId } = req.body;
  try {
    const student = await Student.findByPk(studentId);
    if (!student) {
      res.status(404).json({ message: 'Student not found' });
      return;
    }

    const result = await initiateStkPush(phone, amount, student.admissionNumber);
    res.json(result);
  } catch (error: any) {
    res.status(500).json({ message: 'M-Pesa STK Push failed', error: error.message });
  }
};

export const mpesaCallback = async (req: Request, res: Response): Promise<void> => {
  const { Body } = req.body;
  const result = Body.stkCallback;

  if (result.ResultCode === 0) {
    const amount = result.CallbackMetadata.Item.find((i: any) => i.Name === 'Amount').Value;
    const receipt = result.CallbackMetadata.Item.find((i: any) => i.Name === 'MpesaReceiptNumber').Value;
    const phone = result.CallbackMetadata.Item.find((i: any) => i.Name === 'PhoneNumber').Value;

    const student = await Student.findOne({ where: { guardianPhone: phone.toString().slice(-9) } });
    if (student) {
      await Payment.create({
        studentId: student.id,
        amount,
        method: 'M-PESA',
        transactionId: receipt,
        description: 'Auto-recorded via M-Pesa STK Push'
      });
    }
  }
  res.json({ ResultCode: 0, ResultDesc: 'Success' });
};

