interface MpesaCallbackItem {
  Name: string;
  Value: string | number;
}

// Fix: Using 'any' for req and res to bypass incorrect type definitions in the environment
export const mpesaCallback = async (req: any, res: any): Promise<void> => {
  const { Body } = req.body;
  const result = Body.stkCallback;

  if (result.ResultCode === 0) {
    const metadata = result.CallbackMetadata.Item as MpesaCallbackItem[];
    const amount = metadata.find(i => i.Name === 'Amount')?.Value as number;
    const receipt = metadata.find(i => i.Name === 'MpesaReceiptNumber')?.Value as string;
    const phone = metadata.find(i => i.Name === 'PhoneNumber')?.Value;

    const student = await Student.findOne({ where: { guardianPhone: phone?.toString().slice(-9) } });
    if (student) {
      await Payment.create({
        studentId: student.id,
        amount,
        method: 'M-PESA',
        transactionId: receipt,
        description: 'Auto-recorded via M-Pesa STK Push'
      });
    }
  }
  res.json({ ResultCode: 0, ResultDesc: 'Success' });
};

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { config } from '../config/env';
import { User } from '../models/User';

declare global {
  namespace Express {
    interface Request {
      user?: User;
    }
  }
}

export const protect = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  let token: string | undefined;

  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.startsWith('Bearer')) {
    token = authHeader.split(' ')[1];
  }

  if (!token) {
    res.status(401).json({ message: 'Not authorized, no token provided' });
    return;
  }

  try {
    const decoded = jwt.verify(token, config.JWT_SECRET) as { id: string };
    const user = await User.findByPk(decoded.id);

    if (!user) {
      res.status(401).json({ message: 'User no longer exists' });
      return;
    }

    req.user = user;
    next();
  } catch (error) {
    res.status(401).json({ message: 'Not authorized, token failed' });
  }
};

export const authorize = (...roles: string[]) => {
  return (req: Request, res: Response, next: NextFunction): void => {
    if (!req.user || !roles.includes(req.user.role)) {
      res.status(403).json({ message: `Role ${req.user?.role} is not authorized to access this route` });
      return;
    }
    next();
  };
};

import { Request, Response } from 'express';
import jwt from 'jsonwebtoken';
import bcrypt from 'bcryptjs';
import { User } from '../models/User';
import { config } from '../config/env';

const generateToken = (id: string): string => {
  return jwt.sign({ id }, config.JWT_SECRET, {
    expiresIn: config.JWT_EXPIRES_IN as jwt.SignOptions['expiresIn'],
  });
};

export const login = async (req: Request, res: Response): Promise<void> => {
  const { email, password } = req.body;

  try {
    const user = await User.findOne({ where: { email } });

    if (user && (await bcrypt.compare(password, user.password))) {
      res.json({
        id: user.id,
        name: user.name,
        email: user.email,
        role: user.role,
        token: generateToken(user.id),
      });
    } else {
      res.status(401).json({ message: 'Invalid email or password' });
    }
  } catch (error) {
    res.status(500).json({ message: 'Server error during login', error });
  }
};

