import { Request, Response } from 'express';
import { Mark, Student } from '../models';
import { WhereOptions } from 'sequelize';

const calculateCBCGrade = (score: number): 'EE' | 'ME' | 'AE' | 'BE' => {
  if (score >= 80) return 'EE';
  if (score >= 60) return 'ME';
  if (score >= 40) return 'AE';
  return 'BE';
};

interface MarkEntryInput {
  studentId: string;
  score: number;
  remarks?: string;
  competency?: 'EE' | 'ME' | 'AE' | 'BE';
}

export const bulkUpsertMarks = async (req: Request, res: Response): Promise<void> => {
  try {
    const { examId, subject, entries } = req.body as { examId: string; subject: string; entries: MarkEntryInput[] };

    if (!examId || !subject || !Array.isArray(entries)) {
      res.status(400).json({ message: 'Invalid data format' });
      return;
    }

    const markPromises = entries.map(entry => {
      const score = Number(entry.score);
      return Mark.upsert({
        studentId: entry.studentId,
        examId,
        subject,
        score,
        cbcGrade: entry.competency || calculateCBCGrade(score),
        remarks: entry.remarks || null
      });
    });

    await Promise.all(markPromises);
    res.json({ message: 'Marks updated successfully' });
  } catch (error) {
    res.status(500).json({ message: 'Error recording marks', error });
  }
};

export const getStudentResults = async (req: Request, res: Response): Promise<void> => {
  try {
    const { studentId } = req.params;
    const examId = req.query.examId as string | undefined;

    const where: WhereOptions = { studentId };
    if (examId) where.examId = examId;

    const marks = await Mark.findAll({
      where,
      order: [['subject', 'ASC']]
    });
    res.json(marks);
  } catch (error) {
    res.status(500).json({ message: 'Error fetching results', error });
  }
};

export const getClassResults = async (req: Request, res: Response): Promise<void> => {
  try {
    const examId = req.query.examId as string;
    const subject = req.query.subject as string;
    const { classId } = req.params;

    const marks = await Mark.findAll({
      where: { examId, subject },
      include: [{
        model: Student,
        as: 'student',
        where: { classId: Number(classId) }
      }]
    });
    res.json(marks);
  } catch (error) {
    res.status(500).json({ message: 'Error fetching class results', error });
  }
};

import { Request, Response } from 'express';
import { initiateStkPush } from '../services/mpesaService';
import { Payment, Student } from '../models';

export const stkPush = async (req: Request, res: Response): Promise<void> => {
  const { phone, amount, studentId } = req.body;
  try {
    const student = await Student.findByPk(studentId);
    if (!student) {
      res.status(404).json({ message: 'Student not found' });
      return;
    }

    const result = await initiateStkPush(phone, amount, student.admissionNumber);
    res.json(result);
  } catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error during M-Pesa STK Push';
    res.status(500).json({ message: 'M-Pesa STK Push failed', error: errorMessage });
  }
};

