import React from 'react';
import * as ReactDOMClient from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

// Service Worker Registration for PWA
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    // Only attempt registration on same-origin to prevent scriptURL mismatch errors
    const swUrl = new URL('./sw.js', import.meta.url).href;
    if (new URL(swUrl).origin === window.location.origin) {
      navigator.serviceWorker.register('./sw.js')
        .then(reg => console.log('ElimuSmart PWA: Service Worker Active', reg.scope))
        .catch(err => {
          console.debug('ElimuSmart PWA: SW Registration failed (Safe to ignore in dev)', err.message);
        });
    }
  });
}

const root = ReactDOMClient.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

