import React from 'react';
import * as ReactDOMClient from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

// Service Worker Registration for PWA
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    // Check if current context is secure (required for SW)
    const isLocalhost = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';
    const isHttps = window.location.protocol === 'https:';

    if (isHttps || isLocalhost) {
      // Use simple relative path which is safer across diverse hosting environments
      navigator.serviceWorker.register('./sw.js')
        .then(reg => {
          console.log('ElimuSmart PWA: Service Worker Active', reg.scope);
        })
        .catch(err => {
          console.debug('ElimuSmart PWA: SW Registration skipped', err.message);
        });
    } else {
      console.debug('ElimuSmart PWA: SW skipped (Insecure context)');
    }
  });
}

const root = ReactDOMClient.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

