// Initiate an M-Pesa STK Push prompt to a parent's phone for fee payment
export const stkPush = async (req: any, res: any): Promise<void> => {
  const { phone, amount, studentId } = req.body;
  try {
    // Fix: Cast Student to any for static method findByPk
    const student = await (Student as any).findByPk(studentId);
    if (!student) {
      res.status(404).json({ message: 'Student not found' });
      return;
    }

    const result = await initiateStkPush(phone, amount, student.admissionNumber);
    res.json(result);
  } catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error during M-Pesa STK Push';
    res.status(500).json({ message: 'M-Pesa STK Push failed', error: errorMessage });
  }
};

interface MpesaCallbackItem {
  Name: string;
  Value: string | number;
}

interface MpesaCallbackBody {
  Body: {
    stkCallback: {
      ResultCode: number;
      CallbackMetadata?: {
        Item: MpesaCallbackItem[];
      };
    };
  };
}

// Asynchronous callback handler for M-Pesa transaction results
export const mpesaCallback = async (req: any, res: any): Promise<void> => {
  const { Body } = req.body as MpesaCallbackBody;
  const result = Body.stkCallback;

  if (result.ResultCode === 0 && result.CallbackMetadata) {
    const metadata = result.CallbackMetadata.Item;
    const amount = metadata.find(i => i.Name === 'Amount')?.Value as number;
    const receipt = metadata.find(i => i.Name === 'MpesaReceiptNumber')?.Value as string;
    const phone = metadata.find(i => i.Name === 'PhoneNumber')?.Value;

    // Fix: Cast Student to any for static method findOne
    const student = await (Student as any).findOne({ where: { guardianPhone: phone?.toString().slice(-9) } });
    if (student) {
      // Fix: Cast Payment to any for static method create
      await (Payment as any).create({
        studentId: student.id,
        amount,
        method: 'M-PESA',
        transactionId: receipt,
        description: 'Auto-recorded via M-Pesa STK Push'
      });
    }
  }
  res.json({ ResultCode: 0, ResultDesc: 'Success' });
};

/**
 * ElimuSmart API Service
 * Centralizes all communication with the Render Backend
 */

const API_BASE_URL = 'https://elimusmart-api.onrender.com/api'; // Replace with your actual Render URL if different

export const apiService = {
  getAuthToken() {
    return localStorage.getItem('elimusmart_token');
  },

  async request(endpoint: string, options: RequestInit = {}) {
    const token = this.getAuthToken();
    const headers = {
      'Content-Type': 'application/json',
      ...(token ? { 'Authorization': `Bearer ${token}` } : {}),
      ...options.headers,
    };

    try {
      const response = await fetch(`${API_BASE_URL}${endpoint}`, {
        ...options,
        headers,
      });

      if (response.status === 401) {
        localStorage.removeItem('elimusmart_token');
        window.dispatchEvent(new CustomEvent('unauthorized'));
      }

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.message || `Request failed with status ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error(`API Error [${endpoint}]:`, error);
      throw error;
    }
  },

  async checkHealth() {
    try {
      const res = await fetch(`${API_BASE_URL.replace('/api', '')}/health`);
      return res.ok;
    } catch {
      return false;
    }
  }
};

