      studentName: `${student.firstName} ${student.lastName}`,
      adm: student.admissionNumber,
      class: student.class,
      amount: student.paidFee,
      method: 'CASH',
      reference: 'ACCOUNT STATEMENT',
      date: new Date().toLocaleString(),
      balance: student.feeBalance,
      servedBy: 'Finance Dept'
