  Smartphone,
  Download,
  X
} from 'lucide-react';
import { 
  AreaChart, 
  Area, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer
} from 'recharts';
import { GoogleGenAI } from '@google/genai';
import { User, Student } from '../types';
import { Language, translations } from '../services/localizationService';

interface DashboardProps {
  user: User;
  lang: Language;
  students: Student[];
  installApp?: () => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ user, lang, students = [], installApp }) => {
  const t = translations[lang];
  const [aiBriefing, setAiBriefing] = useState<string>('');
  const [isBriefingLoading, setIsBriefingLoading] = useState(false);
  const [showInstallCard, setShowInstallCard] = useState(true);

  // Calculate accurate statistics from the students source of truth
  const stats = useMemo(() => {
    const totalExpected = students.reduce((sum, s) => sum + (Number(s.totalFee) || 0), 0);
    const totalCollected = students.reduce((sum, s) => sum + (Number(s.paidFee) || 0), 0);
    const totalArrears = students.reduce((sum, s) => sum + (Number(s.feeBalance) || 0), 0);
    const totalPrepaid = students.reduce((sum, s) => sum + (Number(s.prepaidFee) || 0), 0);

    const formatKES = (val: number) => {
      if (val >= 1000000) return (val / 1000000).toFixed(2) + 'M';
      if (val >= 1000) return (val / 1000).toFixed(1) + 'K';
      return val.toLocaleString();
    };

    const collectionRate = totalExpected > 0 ? (totalCollected / totalExpected) * 100 : 0;

    return {
      expected: formatKES(totalExpected),
      collected: formatKES(totalCollected),
      arrears: formatKES(totalArrears),
      prepaid: formatKES(totalPrepaid),
      rawExpected: totalExpected,
      rawCollected: totalCollected,
      studentCount: students.length,
      collectionRate: collectionRate.toFixed(1) + '%',
      attendanceRate: '94.2%',
      enrollmentChange: `+${Math.ceil(students.length * 0.05)} New this term`
    };
  }, [students]);

  // AI Briefing Logic
  useEffect(() => {
    const fetchBriefing = async () => {
      if (!process.env.API_KEY || aiBriefing) return;

      setIsBriefingLoading(true);
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `You are a school management advisor for a Kenyan school. 
          Analyze these current stats:
          - Enrollment: ${stats.studentCount} students
          - Collection Rate: ${stats.collectionRate}
          - Total Collected: KES ${stats.collected}
          - Arrears: KES ${stats.arrears}
          - Attendance: ${stats.attendanceRate}

          Write a short, professional, and punchy 2-sentence executive summary (Principal's Briefing) for the dashboard. Use an encouraging tone.`;

        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: prompt,
        });
        setAiBriefing(response.text || '');
      } catch (e) {
        setAiBriefing("School operations are stable. Focus on fee collection to meet Term 3 targets.");
      } finally {
        setIsBriefingLoading(false);
      }
    };

    fetchBriefing();
  }, [stats]);

  const chartData = useMemo(() => [
    { name: 'Term 1', collection: 3200000 },
    { name: 'Term 2', collection: 4100000 },
    { name: 'Term 3', collection: stats.rawCollected },
  ], [stats.rawCollected]);

  return (
    <div className="space-y-8 animate-in fade-in duration-700">

      {/* PWA Install Invitation Banner */}
      {installApp && showInstallCard && (
        <div className="bg-indigo-600 rounded-[32px] p-6 text-white shadow-xl shadow-indigo-100 flex flex-col md:flex-row items-center justify-between gap-6 animate-in slide-in-from-top-4 duration-500">
           <div className="flex items-center gap-4">
              <div className="w-14 h-14 bg-white/20 rounded-2xl flex items-center justify-center backdrop-blur-md">
                 <Smartphone className="w-8 h-8 text-white" />
              </div>
              <div>
                 <h3 className="text-lg font-black uppercase tracking-tight leading-none">Install ElimuSmart App</h3>
                 <p className="text-[10px] font-bold text-indigo-100 uppercase tracking-widest mt-1">Get instant access from your home screen</p>
              </div>
           </div>
           <div className="flex items-center gap-3">
              <button 
                onClick={installApp}
                className="bg-white text-indigo-600 px-8 py-3 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-indigo-50 transition-all flex items-center gap-2"
              >
                <Download size={14} /> Install Now
              </button>
              <button 
                onClick={() => setShowInstallCard(false)}
                className="p-3 bg-indigo-500/30 hover:bg-indigo-500/50 rounded-2xl transition-all"
              >
                <X size={18} />
              </button>
           </div>
        </div>
      )}

      {/* Principal's Briefing Card */}
      <div className="bg-gradient-to-r from-blue-700 via-blue-800 to-indigo-900 rounded-[40px] p-8 text-white shadow-2xl relative overflow-hidden group">
        <div className="absolute top-0 right-0 p-12 opacity-10 rotate-12 group-hover:scale-110 transition-transform duration-1000">
          <Sparkles size={160} />
        </div>
        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-8">
          <div className="space-y-4 max-w-2xl">
            <div className="flex items-center gap-3">
              <div className="bg-blue-400/20 p-2 rounded-xl backdrop-blur-md border border-white/10">
                <Wand2 className="w-5 h-5 text-blue-200" />
              </div>
              <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-blue-200">AI Principal's Briefing</h2>
            </div>
            {isBriefingLoading ? (
              <div className="flex items-center gap-3 text-blue-200/60 font-medium italic">
                <Loader2 className="w-4 h-4 animate-spin" />
                <span>Generating operational insights...</span>
              </div>
            ) : (
              <p className="text-2xl font-black tracking-tight leading-snug">
                {aiBriefing || "Initializing system diagnostics... Prepare for Term 3 closure reports."}
              </p>
            )}
          </div>
          <div className="bg-white/10 backdrop-blur-xl border border-white/20 p-6 rounded-[32px] shrink-0">
             <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-green-400 rounded-full flex items-center justify-center shadow-lg shadow-green-400/20">
                   <Shield className="w-6 h-6 text-green-900" />
                </div>
                <div>
                   <p className="text-[10px] font-black uppercase tracking-widest text-blue-100">System Integrity</p>
                   <p className="text-xl font-black text-white">OPTIMIZED</p>
                </div>
             </div>
          </div>
        </div>
      </div>

      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-gray-900 tracking-tighter uppercase leading-none">{t.karibu}, {user.name.split(' ')[0]}</h1>
          <p className="text-gray-500 font-medium tracking-tight mt-2">Live School Financial & Operational Overview.</p>
        </div>
        <div className="bg-blue-50 px-4 py-2 rounded-2xl border border-blue-100 hidden md:block">
           <span className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Global Collection Rate: {stats.collectionRate}</span>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: "Total Invoiced", value: stats.expected, icon: Target, color: 'indigo', change: 'Current Year', positive: true },
          { label: "Fees Collected", value: stats.collected, icon: Banknote, color: 'green', change: stats.collectionRate + ' Rate', positive: true },
          { label: "Fee Balances", value: stats.arrears, icon: AlertCircle, color: 'red', change: 'Due Now', positive: false },
          { label: "Prepaid Credit", value: stats.prepaid, icon: Forward, color: 'blue', change: 'Future Terms', positive: true },
        ].map((stat, idx) => {
          const Icon = stat.icon;
          return (
            <div key={idx} className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 flex items-start justify-between group hover:shadow-xl hover:-translate-y-1 transition-all duration-300">
              <div className="min-w-0">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest truncate mb-1">{stat.label}</p>
                <div className="flex items-baseline gap-1">
                   <span className="text-xs font-bold text-gray-300">KES</span>
                   <h3 className={`text-3xl font-black tracking-tighter ${stat.color === 'red' ? 'text-red-600' : stat.color === 'green' ? 'text-green-600' : 'text-gray-900'}`}>{stat.value}</h3>
                </div>
                <div className={`mt-3 flex items-center text-[10px] font-black uppercase tracking-widest ${stat.positive ? 'text-green-600' : 'text-red-500'}`}>
                  {stat.positive ? <CheckCircle className="w-3 h-3 mr-1" /> : <Clock className="w-3 h-3 mr-1" />}
                  {stat.change}
                </div>
              </div>
              <div className={`p-4 rounded-2xl transition-transform group-hover:scale-110 shrink-0 ${
                stat.color === 'blue' ? 'bg-blue-50 text-blue-600' : 
                stat.color === 'green' ? 'bg-green-50 text-green-600' : 
                stat.color === 'red' ? 'bg-red-50 text-red-600' : 
                stat.color === 'indigo' ? 'bg-indigo-50 text-indigo-600' :
                'bg-purple-50 text-purple-600'
              } border-2 border-white shadow-lg shadow-gray-100/50`}>
                <Icon className="w-6 h-6" />
              </div>
            </div>
          );
        })}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100 overflow-hidden flex flex-col group hover:shadow-2xl transition-all duration-500 min-w-0">
          <div className="flex items-center justify-between mb-8">
            <div>
              <h3 className="text-xl font-black text-gray-800 uppercase tracking-tighter">Collection Velocity</h3>
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">Real-time KES Flow</p>
            </div>
            <div className="flex items-center gap-2 bg-gray-50 px-3 py-1.5 rounded-full text-[10px] font-black text-gray-500 uppercase">
              <TrendingUp className="w-3.5 h-3.5" /> Growth Trend
            </div>
          </div>
          <div className="w-full h-[350px] relative min-h-[350px] min-w-0 overflow-hidden bg-gray-50/30 rounded-3xl">
            <ResponsiveContainer width="100%" height="100%" minWidth={0}>
              <AreaChart data={chartData} margin={{ top: 10, right: 10, left: 10, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorColl" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.2}/>
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f8fafc" />
                <XAxis dataKey="name" stroke="#cbd5e1" fontSize={10} fontWeight="900" tickLine={false} axisLine={false} />
                <YAxis hide />
                <Tooltip 
                  cursor={{ stroke: '#2563eb', strokeWidth: 2, strokeDasharray: '5 5' }}
                  contentStyle={{ borderRadius: '24px', border: 'none', boxShadow: '0 25px 50px -12px rgb(0 0 0 / 0.15)', padding: '20px' }}
                  labelStyle={{ fontWeight: '900', textTransform: 'uppercase', fontSize: '12px', color: '#1e293b', marginBottom: '8px' }}
                  formatter={(value: any) => [`KES ${value.toLocaleString()}`, 'Total Collected']}
                />
                <Area type="monotone" dataKey="collection" stroke="#2563eb" strokeWidth={5} fillOpacity={1} fill="url(#colorColl)" animationDuration={2000} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
           <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100 hover:shadow-xl transition-all group">
              <div className="flex items-center gap-4 mb-6">
                 <div className="p-4 bg-blue-50 text-blue-600 rounded-[20px] shadow-sm group-hover:scale-110 transition-transform">
                    <Users className="w-6 h-6" />
                 </div>
                 <div>
                   <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{t.total_students}</p>
                   <p className="text-xs font-bold text-blue-600">Active Learners</p>
                 </div>
              </div>
              <h4 className="text-5xl font-black text-gray-900 tracking-tighter">{students.length}</h4>
              <p className="text-[10px] text-green-600 font-black uppercase mt-4 tracking-widest">{stats.enrollmentChange}</p>
           </div>

           <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100 hover:shadow-xl transition-all group">
              <div className="flex items-center gap-4 mb-6">
                 <div className="p-4 bg-emerald-50 text-emerald-600 rounded-[20px] shadow-sm group-hover:scale-110 transition-transform">
                    <CheckCircle className="w-6 h-6" />
                 </div>
                 <div>
                   <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{t.avg_attendance}</p>
                   <p className="text-xs font-bold text-emerald-600">Daily Average</p>
                 </div>
              </div>
              <h4 className="text-5xl font-black text-gray-900 tracking-tighter">94%</h4>
              <p className="text-[10px] text-blue-600 font-black uppercase mt-4 tracking-widest">Target Met for Term 3</p>
           </div>

           <div className="bg-gradient-to-br from-indigo-700 to-blue-900 p-8 rounded-[48px] shadow-2xl shadow-blue-200 text-white sm:col-span-2 relative overflow-hidden group">
              <div className="absolute top-0 right-0 p-12 opacity-5 rotate-12 group-hover:scale-110 transition-transform duration-700">
                 <Target size={200} />
              </div>
              <div className="relative z-10">
                <div className="flex justify-between items-start mb-10">
                   <div>
                      <h4 className="text-2xl font-black uppercase tracking-tighter">School Health Index</h4>
                      <p className="text-[10px] opacity-70 font-black uppercase tracking-[0.2em] mt-2">Operational Integrity Status</p>
                   </div>
                   <Shield className="w-10 h-10 text-blue-300" />
                </div>
                <div className="space-y-6">
                   <div className="space-y-2">
                      <div className="flex justify-between text-[11px] font-black uppercase tracking-widest">
                         <span>Fee Collection Goal</span>
                         <span className="text-green-300">{stats.collectionRate} Complete</span>
                      </div>
                      <div className="w-full h-2.5 bg-blue-800/50 rounded-full overflow-hidden border border-blue-400/20 shadow-inner">
                         <div className="h-full bg-green-400 shadow-[0_0_15px_rgba(74,222,128,0.5)] transition-all duration-1000" style={{ width: stats.collectionRate }}></div>
                      </div>
                   </div>
                   <div className="space-y-2">
                      <div className="flex justify-between text-[11px] font-black uppercase tracking-widest">
                         <span>SMS Communication</span>
                         <span className="text-blue-300">Live & Active</span>
                      </div>
                      <div className="w-full h-2.5 bg-blue-800/50 rounded-full overflow-hidden border border-blue-400/20 shadow-inner">
                         <div className="h-full bg-blue-300 shadow-[0_0_15px_rgba(147,197,253,0.5)] transition-all duration-1000" style={{ width: '100%' }}></div>
                      </div>
                   </div>
                </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { StudentManagement } from './components/StudentManagement';
import { StaffManagement } from './components/StaffManagement';
import { FinanceModule } from './components/FinanceModule';
import { AttendanceModule } from './components/AttendanceModule';
import { ReportsModule } from './components/ReportsModule';
import { AcademicsModule } from './components/AcademicsModule';
import { SettingsModule } from './components/SettingsModule';
import { TimetableModule } from './components/TimetableModule';
import { MessagingModule } from './components/MessagingModule';
import { UserRole, User, Student, ClassFee, KENYAN_CLASSES, Expenditure, Staff, SMSProvider } from './types';
import { Language } from './services/localizationService';
import { apiService } from './services/apiService';

const getCurrentAcademicCycle = () => {
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();
  let term = 1;
  if (month >= 4 && month <= 7) term = 2;
  else if (month >= 8) term = 3;
  return { year, term };
};

const INITIAL_SCHOOL_CONFIG = {
  schoolName: 'ElimuSmart Academy',
  motto: 'Excellence in Knowledge and Character',
  registrationNo: 'MOE/P/2024/0981',
  year: getCurrentAcademicCycle().year,
  term: getCurrentAcademicCycle().term,
  mpesaPaybill: '522522',
  mpesaTill: '',
  bankName: 'KCB Bank',
  bankAccountNumber: '1100223344',
  smsSettings: {
    provider: SMSProvider.AFRICAS_TALKING,
    username: 'elimusmart_admin',
    apiKey: '***',
    senderId: 'ELIMUSMART',
    enabled: true
  }
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentTab, setCurrentTab] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [lang, setLang] = useState<Language>('en');
  const [isBackendLive, setIsBackendLive] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  // Core Data States
  const [students, setStudents] = useState<Student[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [expenditures, setExpenditures] = useState<Expenditure[]>([]);
  const [feeStructure, setFeeStructure] = useState<ClassFee[]>([]);
  const [schoolConfig, setSchoolConfig] = useState(INITIAL_SCHOOL_CONFIG);
  const [schoolLogo, setSchoolLogo] = useState<string | null>(null);

  // Initialize and check connection
  useEffect(() => {
    const checkConnection = async () => {
      const isLive = await apiService.checkHealth();
      setIsBackendLive(isLive);

      if (isLive && localStorage.getItem('elimusmart_token')) {
        try {
          const profile = await apiService.request('/auth/me');
          setUser(profile);
          fetchCloudData();
        } catch (e) {
          console.debug("Auth session expired");
        }
      } else {
        loadLocalData();
      }
    };
    checkConnection();

    // PWA Install Prompt Listener
    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
      console.log('ElimuSmart: Installation prompt ready');
    });

    window.addEventListener('unauthorized', () => {
      setUser(null);
    });
  }, []);

  const handleInstallApp = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      setDeferredPrompt(null);
    }
  };

  const loadLocalData = () => {
    try {
      const s = localStorage.getItem('elimusmart_students');
      if (s) setStudents(JSON.parse(s));
      const st = localStorage.getItem('elimusmart_staff');
      if (st) setStaff(JSON.parse(st));
      const f = localStorage.getItem('elimusmart_fees');
      if (f) setFeeStructure(JSON.parse(f));
      const c = localStorage.getItem('elimusmart_config');
      if (c) setSchoolConfig(JSON.parse(c));
      setSchoolLogo(localStorage.getItem('elimusmart_logo'));
    } catch (e) {
      console.error("Local load failed");
    }
  };

  const fetchCloudData = async () => {
    setIsSyncing(true);
    try {
      const [cloudStudents, cloudStaff, cloudClasses] = await Promise.all([
        apiService.request('/students'),
        apiService.request('/staff'),
        apiService.request('/classes')
      ]);
      if (cloudStudents) setStudents(cloudStudents);
      if (cloudStaff) setStaff(cloudStaff);
      if (cloudClasses) {
        const fees = cloudClasses.map((c: any) => ({
          className: c.name,
          amount: c.feeStructure?.amount || 0
        }));
        setFeeStructure(fees);
      }
    } catch (e) {
      console.error("Cloud sync failed, using local cache");
    } finally {
      setIsSyncing(false);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    const email = (e.target as any).email.value;
    const password = (e.target as any).password.value;

    if (isBackendLive) {
      try {
        const res = await apiService.request('/auth/login', {
          method: 'POST',
          body: JSON.stringify({ email, password })
        });
        localStorage.setItem('elimusmart_token', res.token);
        setUser(res);
        fetchCloudData();
      } catch (err: any) {
        alert(err.message || "Invalid credentials");
      }
    } else {
      if (email === 'admin@school.ac.ke' && password === 'adminpassword') {
        setUser({ id: 'local-1', name: 'Admin (Offline)', email, role: UserRole.ADMIN });
        loadLocalData();
      } else {
        alert("Incorrect login. Note: System is currently in OFFLINE mode.");
      }
    }
  };

  const logout = () => {
    localStorage.removeItem('elimusmart_token');
    setUser(null);
  };

  useEffect(() => {
    if (students.length > 0) localStorage.setItem('elimusmart_students', JSON.stringify(students));
    if (staff.length > 0) localStorage.setItem('elimusmart_staff', JSON.stringify(staff));
    if (feeStructure.length > 0) localStorage.setItem('elimusmart_fees', JSON.stringify(feeStructure));
    localStorage.setItem('elimusmart_config', JSON.stringify(schoolConfig));
    if (schoolLogo) localStorage.setItem('elimusmart_logo', schoolLogo);
  }, [students, staff, feeStructure, schoolConfig, schoolLogo]);

  if (!user) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
        <div className="bg-white p-10 rounded-[48px] shadow-2xl max-w-md w-full border-2 border-gray-50">
          <div className="text-center mb-8">
            <h1 className="text-4xl font-black text-gray-900 tracking-tighter uppercase italic">ElimuSmart</h1>
            <div className="flex items-center justify-center gap-2 mt-3">
              <div className={`w-2 h-2 rounded-full ${isBackendLive ? 'bg-green-500 animate-pulse' : 'bg-amber-500'}`}></div>
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                {isBackendLive ? 'Cloud Database Ready' : 'Database Offline - Local Mode'}
              </p>
            </div>
          </div>
          <form onSubmit={handleLogin} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Email Address</label>
              <input name="email" type="email" required defaultValue="admin@school.ac.ke" className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl font-bold outline-none focus:border-blue-500" />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Password</label>
              <input name="password" type="password" required defaultValue="adminpassword" className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl font-bold outline-none focus:border-blue-500" />
            </div>
            <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-3xl font-black uppercase tracking-widest hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 active:scale-95">
              Authorize Access
            </button>
          </form>
          {deferredPrompt && (
            <button onClick={handleInstallApp} className="mt-8 w-full flex items-center justify-center gap-2 text-[10px] font-black uppercase text-blue-600 tracking-widest border-2 border-blue-50 py-3 rounded-2xl hover:bg-blue-50 transition-all animate-pulse-indigo">
              Install ElimuSmart App
            </button>
          )}
        </div>
      </div>
    );
  }

  return (
    <Layout 
      user={user} 
      currentTab={currentTab} 
      setCurrentTab={setCurrentTab} 
      isSidebarOpen={isSidebarOpen} 
      setIsSidebarOpen={setIsSidebarOpen}
      logout={logout}
      lang={lang}
      setLang={setLang}
      isBackendLive={isBackendLive}
      isSyncing={isSyncing}
      installApp={deferredPrompt ? handleInstallApp : undefined}
    >
      <div className="p-4 md:p-8">
        {currentTab === 'dashboard' && <Dashboard user={user} lang={lang} students={students} installApp={deferredPrompt ? handleInstallApp : undefined} />}
        {currentTab === 'students' && <StudentManagement students={students} setStudents={setStudents} feeStructure={feeStructure} />}
        {currentTab === 'staff' && <StaffManagement staffList={staff} setStaffList={setStaff} />}
        {currentTab === 'finance' && <FinanceModule lang={lang} students={students} setStudents={setStudents} expenditures={expenditures} setExpenditures={setExpenditures} feeStructure={feeStructure} setFeeStructure={setFeeStructure} schoolLogo={schoolLogo} schoolConfig={schoolConfig} isBackendLive={isBackendLive} />}
        {currentTab === 'attendance' && <AttendanceModule lang={lang} students={students} />}
        {currentTab === 'academics' && <AcademicsModule lang={lang} students={students} setStudents={setStudents} schoolConfig={schoolConfig} />}
        {currentTab === 'reports' && <ReportsModule lang={lang} students={students} users={[]} schoolLogo={schoolLogo} schoolConfig={schoolConfig} />}
        {currentTab === 'timetable' && <TimetableModule lang={lang} />}
        {currentTab === 'messaging' && <MessagingModule lang={lang} user={user} students={students} schoolConfig={schoolConfig} setSchoolConfig={setSchoolConfig} />}
        {currentTab === 'settings' && <SettingsModule currentUser={user} users={[]} setUsers={() => {}} schoolLogo={schoolLogo} setSchoolLogo={setSchoolLogo} schoolConfig={schoolConfig} setSchoolConfig={setSchoolConfig} />}
      </div>
    </Layout>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { 
  AlertCircle, 
  Loader2, 
  Printer, 
  Download, 
  Target, 
  Banknote, 
  Forward, 
  CreditCard, 
  Save, 
  ShieldAlert, 
  Zap, 
  X, 
  CheckCircle2, 
  FileDown,
  User,
  Hash,
  Smartphone,
  Search,
  FileSpreadsheet,
  ShieldCheck,
  ReceiptText,
  TrendingDown,
  ChevronRight,
  Plus,
  Settings2,
  FileText,
  Edit3,
  Trash2,
  AlertTriangle,
  ArrowRight,
  Wallet,
  UserSearch
} from 'lucide-react';
import { Language, translations } from '../services/localizationService';
import { KENYAN_CLASSES, Student, ClassFee, Expenditure } from '../types';
import { apiService } from '../services/apiService';

interface Props {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  expenditures: Expenditure[];
  setExpenditures: React.Dispatch<React.SetStateAction<Expenditure[]>>;
  feeStructure: ClassFee[];
  setFeeStructure: React.Dispatch<React.SetStateAction<ClassFee[]>>;
  schoolLogo: string | null;
  schoolConfig: any;
  isBackendLive?: boolean;
}

interface TransactionReceipt {
  receiptNo: string;
  studentName: string;
  adm: string;
  class: string;
  amount: number;
  method: 'M-PESA' | 'BANK' | 'CASH';
  reference: string;
  date: string;
  balance: number;
  servedBy: string;
}

export const FinanceModule: React.FC<Props & { lang: Language }> = ({ lang, students, setStudents, expenditures, setExpenditures, feeStructure, setFeeStructure, schoolLogo, schoolConfig, isBackendLive }) => {
  const t = translations[lang];

  const [activeTab, setActiveTab] = useState<'payments' | 'class-summary' | 'fee-structure' | 'expenditures'>('class-summary');
  const [selectedClass, setSelectedClass] = useState<string>('All Classes');
  const [financeSearch, setFinanceSearch] = useState('');
  const [showReceipt, setShowReceipt] = useState(false);
  const [lastReceipt, setLastReceipt] = useState<TransactionReceipt | null>(null);

  // Global Collection States
  const [isQuickCollectOpen, setIsQuickCollectOpen] = useState(false);
  const [quickSearchTerm, setQuickSearchTerm] = useState('');

  // Payment Recording states
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
  const [selectedStudentForPayment, setSelectedStudentForPayment] = useState<Student | null>(null);
  const [paymentFormData, setPaymentFormData] = useState({ amount: '', method: 'CASH' as 'CASH' | 'BANK', reference: '' });

  // STK Push states
  const [isStkModalOpen, setIsStkModalOpen] = useState(false);
  const [stkStudent, setStkStudent] = useState<Student | null>(null);
  const [stkAmount, setStkAmount] = useState('');
  const [stkPhone, setStkPhone] = useState('');
  const [isStkProcessing, setIsStkProcessing] = useState(false);

  // Billing states
  const [isBillingModalOpen, setIsBillingModalOpen] = useState(false);
  const [selectedStudentForBilling, setSelectedStudentForBilling] = useState<Student | null>(null);
  const [billingFormData, setBillingFormData] = useState({ agreedFee: 0, paidFee: 0 });

  // Expenditure management states
  const [showExpModal, setShowExpModal] = useState(false);
  const [editingExpId, setEditingExpId] = useState<string | null>(null);
  const [expForm, setExpForm] = useState<Partial<Expenditure>>({
    amount: 0,
    category: 'Other',
    date: new Date().toISOString().split('T')[0],
    description: ''
  });

  const filteredStudents = useMemo(() => {
    return (students || []).filter(s => {
      const matchesClass = selectedClass === 'All Classes' || s.class === selectedClass;
      const term = financeSearch.toLowerCase();
      return matchesClass && (s.firstName.toLowerCase().includes(term) || s.lastName.toLowerCase().includes(term) || s.admissionNumber.toLowerCase().includes(term));
    });
  }, [students, selectedClass, financeSearch]);

  const quickFilterStudents = useMemo(() => {
    if (!quickSearchTerm) return [];
    return (students || []).filter(s => 
      s.firstName.toLowerCase().includes(quickSearchTerm.toLowerCase()) || 
      s.lastName.toLowerCase().includes(quickSearchTerm.toLowerCase()) || 
      s.admissionNumber.toLowerCase().includes(quickSearchTerm.toLowerCase())
    ).slice(0, 5);
  }, [students, quickSearchTerm]);

  const financeStats = useMemo(() => {
    const totalCollected = students.reduce((sum, s) => sum + (s.paidFee || 0), 0);
    const totalExp = expenditures.reduce((sum, e) => sum + e.amount, 0);
    return { 
      expected: students.reduce((sum, s) => sum + (s.agreedFee ?? s.totalFee), 0),
      collected: totalCollected, 
      outstanding: students.reduce((sum, s) => sum + (s.feeBalance || 0), 0), 
      prepaid: students.reduce((sum, s) => sum + (s.prepaidFee || 0), 0),
      expenditure: totalExp,
      net: totalCollected - totalExp 
    };
  }, [students, expenditures]);

  const initiateStkPush = (student: Student) => {
    setStkStudent(student);
    setStkAmount(student.feeBalance.toString());
    setStkPhone(student.guardianPhone);
    setIsStkModalOpen(true);
  };

  const openPaymentModal = (student: Student) => {
    setSelectedStudentForPayment(student);
    setPaymentFormData({ amount: '', method: 'CASH', reference: '' });
    setIsPaymentModalOpen(true);
    setIsQuickCollectOpen(false); // Close search if it was open
  };

  const handleSavePayment = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedStudentForPayment || !paymentFormData.amount) return;

    const amountToAdd = parseFloat(paymentFormData.amount);
    setStudents(prev => prev.map(s => {
      if (s.id === selectedStudentForPayment.id) {
        const totalPaid = (s.paidFee || 0) + amountToAdd;
        const target = s.agreedFee ?? s.totalFee;
        const balance = Math.max(0, target - totalPaid);
        const prepaid = totalPaid > target ? totalPaid - target : 0;

        // Generate receipt
        setLastReceipt({
          receiptNo: `RCT-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
          studentName: `${s.firstName} ${s.lastName}`,
          adm: s.admissionNumber,
          class: s.class,
          amount: amountToAdd,
          method: paymentFormData.method as any,
          reference: paymentFormData.reference || 'DIRECT COLLECTION',
          date: new Date().toLocaleString(),
          balance: balance,
          servedBy: 'Institutional Finance'
        });

        return { ...s, paidFee: totalPaid, feeBalance: balance, prepaidFee: prepaid };
      }
      return s;
    }));

    setIsPaymentModalOpen(false);
    setShowReceipt(true);
  };

  const handleConfirmStk = async () => {
    if (!stkStudent || !stkAmount) return;
    setIsStkProcessing(true);
    try {
      if (isBackendLive) {
        await apiService.request('/mpesa/stk-push', {
          method: 'POST',
          body: JSON.stringify({
            studentId: stkStudent.id,
            amount: parseFloat(stkAmount),
            phone: stkPhone
          })
        });
        alert("STK Push initiated! A prompt has been sent to the guardian's phone.");
      } else {
        await new Promise(r => setTimeout(r, 2000));
        alert("OFFLINE MODE: STK Push simulated. In production, this would send a real Safaricom prompt.");
      }
      setIsStkModalOpen(false);
    } catch (e: any) {
      alert("M-Pesa Error: " + (e.message || "Could not connect to Safaricom Daraja API"));
    } finally {
      setIsStkProcessing(false);
    }
  };

  const openBillingEditor = (student: Student) => {
    setSelectedStudentForBilling(student);
    setBillingFormData({ agreedFee: student.agreedFee ?? student.totalFee, paidFee: student.paidFee || 0 });
    setIsBillingModalOpen(true);
  };

  const handleSaveBilling = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedStudentForBilling) return;
    setStudents(prev => prev.map(s => {
      if (s.id === selectedStudentForBilling.id) {
        const target = billingFormData.agreedFee;
        const paid = billingFormData.paidFee;
        let balance = Math.max(0, target - paid);
        let prepaid = paid > target ? paid - target : 0;
        return { ...s, agreedFee: target, paidFee: paid, feeBalance: balance, prepaidFee: prepaid };
      }
      return s;
    }));
    setIsBillingModalOpen(false);
  };

  const generateStudentReceipt = (student: Student) => {
    setLastReceipt({
      receiptNo: `STA-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      studentName: `${student.firstName} ${student.lastName}`,
      adm: student.admissionNumber,
      class: student.class,
      amount: student.paidFee,
      method: 'CASH',
      reference: 'ACCOUNT STATEMENT',
      date: new Date().toLocaleString(),
      balance: student.feeBalance,
      servedBy: 'Finance Dept'
    });
    setShowReceipt(true);
  };

  const handleSaveExpenditure = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingExpId) {
      setExpenditures(prev => prev.map(exp => exp.id === editingExpId ? { ...exp, ...expForm } as Expenditure : exp));
    } else {
      const newExp = { ...expForm, id: Math.random().toString(36).substr(2, 9) } as Expenditure;
      setExpenditures(prev => [newExp, ...prev]);
    }
    setShowExpModal(false);
    setEditingExpId(null);
  };

  const openExpEditor = (exp?: Expenditure) => {
    if (exp) {
      setEditingExpId(exp.id);
      setExpForm(exp);
    } else {
      setEditingExpId(null);
      setExpForm({
        amount: 0,
        category: 'Other',
        date: new Date().toISOString().split('T')[0],
        description: ''
      });
    }
    setShowExpModal(true);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tight uppercase">{t.finance}</h1>
          <p className="text-gray-500 font-medium">Manage institutional revenue and integrated M-Pesa payments.</p>
        </div>
        <div className="flex gap-2">
           <button 
             onClick={() => openExpEditor()}
             className="flex items-center gap-2 bg-white border-2 border-gray-100 px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-gray-50 transition-all shadow-sm"
           >
             <TrendingDown className="w-4 h-4 text-red-600" /> New Expense
           </button>
           <button 
             onClick={() => setIsQuickCollectOpen(true)}
             className="flex items-center gap-2 bg-blue-600 text-white px-8 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 animate-pulse-install"
           >
             <Banknote className="w-4 h-4" /> Collect Fee
           </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { label: t.total_expected, value: financeStats.expected, icon: Target, color: 'indigo' },
          { label: t.collected_fee, value: financeStats.collected, icon: Banknote, color: 'green' },
          { label: t.outstanding_fees, value: financeStats.outstanding, icon: AlertCircle, color: 'red' },
          { label: 'Expenditures', value: financeStats.expenditure, icon: TrendingDown, color: 'orange' }
        ].map((stat, idx) => (
          <div key={idx} className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm flex items-center gap-4">
             <div className="p-3 rounded-xl bg-gray-50">
                <stat.icon size={20} className={`text-${stat.color}-600`} />
             </div>
             <div>
                <p className="text-[9px] font-black uppercase text-gray-400 tracking-widest">{stat.label}</p>
                <p className="text-lg font-black text-gray-900 leading-tight">KES {stat.value.toLocaleString()}</p>
             </div>
          </div>
        ))}
      </div>

      <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden">
        <div className="flex border-b overflow-x-auto">
          {[
            { id: 'class-summary', label: 'Learner Ledger', icon: ReceiptText },
            { id: 'expenditures', label: 'Expenditures', icon: TrendingDown },
            { id: 'fee-structure', label: 'Fee Structure', icon: Settings2 },
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`px-8 py-5 text-[10px] font-black uppercase tracking-widest flex items-center gap-3 transition-all border-b-2 whitespace-nowrap ${activeTab === tab.id ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400 hover:text-gray-900'}`}
            >
              <tab.icon size={16} /> {tab.label}
            </button>
          ))}
        </div>

        <div className="p-8">
          {activeTab === 'class-summary' && (
            <div className="space-y-6">
               <div className="flex flex-col md:flex-row gap-4 justify-between">
                  <div className="flex-1 relative">
                     <Search className="absolute left-4 top-3 w-5 h-5 text-gray-400" />
                     <input 
                      type="text" 
                      placeholder="Search learners by name or ADM..." 
                      value={financeSearch}
                      onChange={e => setFinanceSearch(e.target.value)}
                      className="w-full pl-12 pr-4 py-2.5 bg-gray-50 border-2 border-transparent rounded-xl focus:bg-white focus:border-blue-500 transition-all outline-none"
                     />
                  </div>
                  <select 
                    value={selectedClass} 
                    onChange={e => setSelectedClass(e.target.value)}
                    className="p-2.5 border-2 rounded-xl text-[10px] font-black uppercase tracking-widest outline-none"
                  >
                    <option>All Classes</option>
                    {KENYAN_CLASSES.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
               </div>

               <div className="overflow-x-auto">
                 <table className="w-full text-left">
                   <thead>
                     <tr className="text-[9px] font-black uppercase text-gray-400 tracking-widest border-b pb-4">
                       <th className="pb-4 px-2">Learner Name</th>
                       <th className="pb-4 px-2">Grade</th>
                       <th className="pb-4 px-2">Balance</th>
                       <th className="pb-4 px-2 text-right">Actions</th>
                     </tr>
                   </thead>
                   <tbody className="divide-y divide-gray-50">
                     {filteredStudents.map(student => (
                       <tr key={student.id} className="hover:bg-gray-50/50 transition-colors">
                         <td className="py-4 px-2">
                            <p className="font-bold text-gray-900">{student.firstName} {student.lastName}</p>
                            <p className="text-[9px] font-mono text-blue-600 uppercase tracking-tighter">{student.admissionNumber}</p>
                         </td>
                         <td className="py-4 px-2"><span className="px-2 py-0.5 bg-gray-100 rounded text-[9px] font-black uppercase">{student.class}</span></td>
                         <td className="py-4 px-2">
                            <p className={`text-xs font-black ${student.feeBalance > 0 ? 'text-red-600' : 'text-green-600'}`}>
                               KES {(student.feeBalance || 0).toLocaleString()}
                            </p>
                         </td>
                         <td className="py-4 px-2 text-right">
                            <div className="flex justify-end gap-2">
                               <button 
                                 onClick={() => openPaymentModal(student)} 
                                 className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 text-blue-700 rounded-lg text-[9px] font-black uppercase tracking-widest border border-blue-100 hover:bg-blue-100 transition-all shadow-sm"
                               >
                                  <CreditCard size={12} /> Record Payment
                               </button>
                               <button 
                                 onClick={() => initiateStkPush(student)} 
                                 className="flex items-center gap-2 px-3 py-1.5 bg-green-50 text-green-700 rounded-lg text-[9px] font-black uppercase tracking-widest border border-green-100 hover:bg-green-100 transition-all shadow-sm"
                               >
                                  <Smartphone size={12} /> STK Push
                               </button>
                               <button onClick={() => openBillingEditor(student)} className="p-2 text-gray-400 hover:text-blue-600" title="Adjust Billing"><Settings2 size={16} /></button>
                               <button onClick={() => generateStudentReceipt(student)} className="p-2 text-gray-400 hover:text-green-600" title="Print Statement"><Printer size={16} /></button>
                            </div>
                         </td>
                       </tr>
                     ))}
                   </tbody>
                 </table>
               </div>
            </div>
          )}

          {activeTab === 'expenditures' && (
            <div className="space-y-6">
               <div className="flex justify-between items-center">
                  <h3 className="text-sm font-black uppercase tracking-tight text-gray-900">Institutional Expenses</h3>
                  <button onClick={() => openExpEditor()} className="flex items-center gap-2 bg-gray-900 text-white px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-black transition-all">
                     <Plus size={14} /> Add Record
                  </button>
               </div>
               <div className="overflow-x-auto">
                 <table className="w-full text-left">
                   <thead>
                     <tr className="text-[9px] font-black uppercase text-gray-400 tracking-widest border-b pb-4">
                       <th className="pb-4">Date</th>
                       <th className="pb-4">Category</th>
                       <th className="pb-4">Description</th>
                       <th className="pb-4">Amount</th>
                       <th className="pb-4 text-right">Edit</th>
                     </tr>
                   </thead>
                   <tbody className="divide-y divide-gray-50">
                     {expenditures.map(exp => (
                       <tr key={exp.id} className="hover:bg-gray-50/50 transition-colors">
                         <td className="py-4 text-xs font-bold">{new Date(exp.date).toLocaleDateString()}</td>
                         <td className="py-4"><span className="px-2 py-0.5 bg-gray-100 rounded text-[9px] font-black uppercase">{exp.category}</span></td>
                         <td className="py-4 text-xs text-gray-600">{exp.description}</td>
                         <td className="py-4 font-black text-gray-900">KES {exp.amount.toLocaleString()}</td>
                         <td className="py-4 text-right">
                            <button onClick={() => openExpEditor(exp)} className="p-2 text-gray-400 hover:text-blue-600"><Edit3 size={16} /></button>
                         </td>
                       </tr>
                     ))}
                     {expenditures.length === 0 && (
                       <tr>
                         <td colSpan={5} className="py-12 text-center text-gray-400 font-bold uppercase text-[10px]">No expenditure records found.</td>
                       </tr>
                     )}
                   </tbody>
                 </table>
               </div>
            </div>
          )}

          {activeTab === 'fee-structure' && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
               {feeStructure.map((fee, idx) => (
                 <div key={idx} className="p-5 bg-gray-50 rounded-2xl border border-gray-100 flex items-center justify-between">
                    <div>
                       <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest">{fee.className}</p>
                       <p className="text-lg font-black text-gray-900">KES {fee.amount.toLocaleString()}</p>
                    </div>
                    <button 
                      onClick={() => {
                        const amt = prompt(`New fee amount for ${fee.className}`, fee.amount.toString());
                        if (amt && !isNaN(Number(amt))) {
                          setFeeStructure(prev => prev.map(f => f.className === fee.className ? { ...f, amount: Number(amt) } : f));
                        }
                      }}
                      className="p-3 bg-white text-gray-400 hover:text-blue-600 rounded-xl shadow-sm border border-gray-100 transition-all"
                    >
                      <Edit3 size={16} />
                    </button>
                 </div>
               ))}
            </div>
          )}
        </div>
      </div>

      {/* Global Quick Collect Modal */}
      {isQuickCollectOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-gray-900/80 backdrop-blur-md">
           <div className="bg-white rounded-[40px] w-full max-w-lg shadow-2xl p-10 animate-in zoom-in duration-300">
              <div className="flex justify-between items-center mb-8">
                 <div>
                    <h2 className="text-2xl font-black text-gray-900 uppercase tracking-tighter">Quick Collect</h2>
                    <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mt-1">Search for a Learner</p>
                 </div>
                 <button onClick={() => setIsQuickCollectOpen(false)} className="text-gray-400 hover:text-red-600"><X size={24} /></button>
              </div>
              <div className="space-y-6">
                 <div className="relative">
                    <UserSearch className="absolute left-4 top-4 text-gray-400" />
                    <input 
                      autoFocus
                      type="text" 
                      placeholder="Type Learner Name or ADM No..." 
                      value={quickSearchTerm}
                      onChange={e => setQuickSearchTerm(e.target.value)}
                      className="w-full pl-12 pr-4 py-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold focus:border-blue-500 outline-none shadow-inner"
                    />
                 </div>
                 <div className="space-y-2">
                    {quickFilterStudents.map(s => (
                       <button 
                        key={s.id} 
                        onClick={() => openPaymentModal(s)}
                        className="w-full flex items-center justify-between p-4 bg-white border-2 border-gray-100 rounded-2xl hover:border-blue-500 hover:bg-blue-50 transition-all group"
                       >
                          <div className="text-left">
                             <p className="font-black text-gray-900 uppercase italic">{s.firstName} {s.lastName}</p>
                             <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{s.admissionNumber} • {s.class}</p>
                          </div>
                          <div className="flex items-center gap-3">
                             <div className="text-right">
                                <p className="text-[9px] font-black text-gray-300 uppercase">Balance</p>
                                <p className="font-black text-red-600">KES {s.feeBalance.toLocaleString()}</p>
                             </div>
                             <ChevronRight className="text-blue-500 group-hover:translate-x-1 transition-transform" />
                          </div>
                       </button>
                    ))}
                    {quickSearchTerm && quickFilterStudents.length === 0 && (
                       <div className="py-8 text-center text-gray-400 font-bold uppercase text-[10px] italic tracking-widest">No matching learners found.</div>
                    )}
                    {!quickSearchTerm && (
                       <div className="py-12 text-center">
                          <AlertCircle className="w-10 h-10 text-gray-100 mx-auto mb-3" />
                          <p className="text-[10px] text-gray-300 font-black uppercase tracking-[0.3em]">Start typing to find accounts</p>
                       </div>
                    )}
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Manual Payment Collection Modal */}
      {isPaymentModalOpen && selectedStudentForPayment && (
